/**
 * Trello Node - Version 1
 * Discriminator: resource=checklist, operation=create
 */


interface Credentials {
  trelloApi: CredentialReference;
  trelloOAuth1Api: CredentialReference;
}

/** Create a new attachment for a card */
export type TrelloV1ChecklistCreateParams = {
  resource: 'checklist';
  operation: 'create';
  authentication?: 'apiKey' | 'oAuth1' | Expression<string>;
/**
 * The ID of the card
 * @searchListMethod searchCards
 * @default {"mode":"list","value":""}
 */
    cardId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * The URL of the checklist to add
 */
    name: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** The ID of a source checklist to copy into the new one
     */
    idChecklistSource?: string | Expression<string>;
    /** The position of the checklist on the card. One of: top, bottom, or a positive number.
     */
    pos?: string | Expression<string>;
  };
};

export type TrelloV1ChecklistCreateOutput = {
  checkItems?: Array<{
    due?: null;
    dueReminder?: number;
    id?: string;
    idChecklist?: string;
    idMember?: null;
    name?: string;
    pos?: number;
    state?: string;
  }>;
  id?: string;
  idBoard?: string;
  idCard?: string;
  name?: string;
  pos?: number;
};

export type TrelloV1ChecklistCreateNode = {
  type: 'n8n-nodes-base.trello';
  version: 1;
  config: NodeConfig<TrelloV1ChecklistCreateParams> & { credentials?: Credentials };
  output?: Items<TrelloV1ChecklistCreateOutput>;
};